		DisplayName:    droidCustomModelDisplayName,
		Model:          droidCustomModelBaseID,
		BaseURL:        "https://api.anthropic.com",
		APIKey:         apiKey,
		Provider:       "anthropic",
		MaxOutputToken: 8192,
	}

